	const prefix = "OPENCODE_CONFIG_CONTENT="
	config := map[string]any{}
	result := make([]string, 0, len(env)+1)
	for _, item := range env {
		if !strings.HasPrefix(item, prefix) {
			result = append(result, item)
			continue
